.eon8-live-page .whatwedo-section {
  padding: 20px 20px;
  text-align: center;
  font-family: Arial, sans-serif;
}
.eon8-live-page .section-title {
  font-size: 32px;
  font-weight: 700;
  margin-bottom: 10px;
}
.eon8-live-page .section-subtitle {
  max-width: 800px;
  margin: 0 auto 10px;
  color: #555;
  line-height: 1.6;
}
.eon8-live-page .whatwedo-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 25px;
  margin-top: 40px;
}
.eon8-live-page .what-card {
  background: #dfe6ef;
  padding: 30px 25px;
  border-radius: 14px;
  text-align: center;
  transition: all 0.4s ease;
  opacity: 0;
  transform: translateY(40px);
}
.eon8-live-page .what-card:hover {
  transform: translateY(-10px) scale(1.02);
  box-shadow: 0 20px 40px rgba(0,0,0,0.12);
}
.eon8-live-page .icon-circle {
  width: 70px;
  height: 70px;
  margin: 0 auto 15px;
  border-radius: 50%;
  background: linear-gradient(135deg, #0052cc, #003a99);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: pulse 2s infinite;
}
.eon8-live-page .icon-circle i {
  color: #fff;
  font-size: 26px;
}
.eon8-live-page .what-card h3 {
  font-size: 18px;
  margin-bottom: 10px;
}
.eon8-live-page .what-card p {
  font-size: 14px;
  color: #333;
  margin-bottom: 10px;
}
.eon8-live-page .what-card ul {
  text-align: left;
  padding-left: 18px;
  font-size: 14px;
  color: #333;
}
.eon8-live-page .what-card ul li {
  margin-bottom: 6px;
}
.eon8-live-page .card-highlight {
  margin-top: 10px;
  font-weight: 600;
}
.eon8-live-page .animate {
  opacity: 0;
  transform: translateY(40px);
}
.eon8-live-page .animate.show {
  opacity: 1;
  transform: translateY(0);
  transition: all 0.8s ease;
}
.eon8-live-page .delay-1 { transition-delay: 0.2s; }
.eon8-live-page .delay-2 { transition-delay: 0.4s; }
.eon8-live-page .delay-3 { transition-delay: 0.6s; }
@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.08); }
  100% { transform: scale(1); }
}
@media (max-width: 992px) {.eon8-live-page .whatwedo-grid {
    grid-template-columns: repeat(2, 1fr);
  }}
@media (max-width: 576px) {.eon8-live-page .whatwedo-grid {
    grid-template-columns: 1fr;
  }}
